# Studyo 0.5.53 yamasi: yapay zeka denetimi Studyo'da (Google Gemini Flash-Lite; Hazirlik 0.5.3 kurallari). Turkce kitap islenince
# denetim, sonra Osmanlica ve ciktilar; ayni anda 3 kitap; gunluk sinir dolunca ertesi gun surer. Seslendirme kendiliginden ayarla.
# 0.5.52 uzerine. Kod klasorunde: cd /DATA/AppData/dedplay-studyo/kod/studyo && python3 studyo_0553_yama.py
# Tekrar calistirilabilir: dosya zaten yeniyse ATLANDI; ne eski ne yeniyse hicbir seye dokunmadan HATA.
import base64, hashlib, os, sys, zlib
D = [
    ('kutuphane/yz.py', None, '0884fcd3daf708ca2fe518d3cda1c066',
     ''),
    ('kutuphane/denetim.py', None, '1c1ad68715796fb8a83075daf1204e2f',
     ''),
    ('kutuphane/depo.py', 'dfd907f2bc0adc1164e53d18feb09d66', '6ca9fbbb03b85a805840552fd0e07daa',
     ''),
    ('kutuphane/main.py', '0f47269d165c579c6f902bbb3d27abce', 'bef7734a47678344529780db4c56670c',
     ''),
    ('kutuphane/static/index.html', '90982b3f63b3fe1cf657d45de5148f10', '5772f3ac54f35f293ca7ca1c2d0bb6b9',
     ''),
    ('tests/test_0553.py', None, 'afa1de685fbf3355b548d248cd220b1f',
     ''),
    ('tests/test_zincir.py', '4e40e53e3f04954dac4ef7af42adc8c6', '3edebc224844a4ca8191386e1582b827',
     ''),
    ('tests/test_duzeltme.py', 'c2feff6f3a6a61df6e0b0180edb54586', '9dc6ee58eb43734d04731df84a457fff',
     ''),
]
md5 = lambda p: hashlib.md5(open(p, 'rb').read()).hexdigest() if os.path.exists(p) else None
for yol, eski, yeni, _ in D:
    m = md5(yol)
    if m not in (eski, yeni):
        print('HATA:', yol, 'beklenmeyen icerik (md5', m, ') - hicbir dosya degistirilmedi'); sys.exit(1)
for yol, eski, yeni, veri in D:
    if md5(yol) == yeni:
        print('ATLANDI (zaten yeni):', yol); continue
    icerik = zlib.decompress(base64.b64decode(veri))
    assert hashlib.md5(icerik).hexdigest() == yeni
    open(yol, 'wb').write(icerik)
    print('YAZILDI:', yol, yeni)
print('TAMAM')
